def sum_list(lst):
    total = 0
    for x in lst:
        total += x
    return total

def factorial(n):
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def power(base, exp):
    result = 1
    for _ in range(exp):
        result *= base
    return result
